local sliding, sliderTouch, dragging, dragStart, panelStart = false, nil, false, nil, nil
local dragInput
local function slide(x)
    speed = MIN_SPEED + math.floor(math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1) * (MAX_SPEED - MIN_SPEED) + 0.5)
    speedLabel.Text = "Walk speed: " .. speed
    fill.Size = UDim2.fromScale((speed - MIN_SPEED) / (MAX_SPEED - MIN_SPEED), 1)
    thumb.Position = UDim2.fromScale((speed - MIN_SPEED) / (MAX_SPEED - MIN_SPEED), 0.5)
end
connect(track.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        sliding, sliderTouch = true, input
        slide(input.Position.X)
    end
end)

-- RESOURCE LOGO DATA
local resourceLogoBase64 = ""
-- END RESOURCE LOGO DATA

-- Optional uploaded Roblox image ID for environments without custom-image APIs.
local resourceLogoAssetId = ""
local resourceGearAssetId = ""
local resourceGearBase64 = ""
local function decodeLogo(encoded)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local values, decoded = {}, {}
    for i = 1, #alphabet do values[alphabet:sub(i, i)] = i - 1 end
    for i = 1, #encoded, 4 do
        local a, b = values[encoded:sub(i, i)], values[encoded:sub(i + 1, i + 1)]
        local c, d = values[encoded:sub(i + 2, i + 2)], values[encoded:sub(i + 3, i + 3)]
        local packed = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
        decoded[#decoded + 1] = string.char(math.floor(packed / 65536) % 256)
        if c then decoded[#decoded + 1] = string.char(math.floor(packed / 256) % 256) end
        if d then decoded[#decoded + 1] = string.char(packed % 256) end
    end
    return table.concat(decoded)
end
local function loadResourceImage(encoded, filename, uploadedId)
    if uploadedId ~= "" then return uploadedId end
    local registerAsset = getcustomasset or getsynasset
    if type(writefile) ~= "function" or type(registerAsset) ~= "function" then return nil end
    local ok, asset = pcall(function()
        writefile(filename, decodeLogo(encoded))
        return registerAsset(filename)
    end)
    if ok and type(asset) == "string" and asset ~= "" then return asset end
    return nil
end
task.spawn(function()
    local intro, rollingGear
    local function animate(object, duration, properties, easing)
        if not alive then return false end
        local tween = TweenService:Create(object, TweenInfo.new(duration, easing or Enum.EasingStyle.Quad, Enum.EasingDirection.Out), properties)
        tween:Play()
        tween.Completed:Wait()
        return alive
    end
    local ok, err = pcall(function()
        local asset = loadResourceImage(resourceLogoBase64, "ResourceIncremental_Halloween_logo_v1.png", resourceLogoAssetId)
        local gearAsset = loadResourceImage(resourceGearBase64, "ResourceIncremental_Halloween_gear_v1.png", resourceGearAssetId)
        if not asset or not alive then return end
        intro = new("CanvasGroup", {
            AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(600, 400), BackgroundTransparency = 1, ZIndex = 20,
        }, gui)
        local viewport = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(800, 600)
        new("UIScale", {Scale = math.min(1, (viewport.X - 24) / 600, (viewport.Y - 24) / 400)}, intro)
        if gearAsset then
            rollingGear = new("ImageLabel", {
                AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, -80, 0.5, 0),
                Size = UDim2.fromOffset(128, 128), Image = gearAsset, ScaleType = Enum.ScaleType.Fit,
                BackgroundTransparency = 1, ImageTransparency = 1, ZIndex = 21,
            }, gui)
        end
        local reveal = new("Frame", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(0.5, 260, 0.5, 0),
            Size = UDim2.fromOffset(0, 350), BackgroundTransparency = 1, ClipsDescendants = true,
        }, intro)
        local logo = new("ImageLabel", {
            AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.fromScale(1, 0.5),
            Size = UDim2.fromOffset(520, 350), Image = asset, ScaleType = Enum.ScaleType.Fit,
            BackgroundTransparency = 1, ImageTransparency = 1,
        }, reveal)
        local loaded = false
        task.spawn(function()
            pcall(function() ContentProvider:PreloadAsync(rollingGear and {logo, rollingGear} or {logo}) end)
            loaded = true
        end)
        local deadline = os.clock() + 1
        while alive and not loaded and os.clock() < deadline do task.wait(0.03) end
        if rollingGear then
            rollingGear.ImageTransparency = 0
            -- Match clockwise rotation to the horizontal distance travelled.
            local rotation = (viewport.X + 160) / 64 * 180 / math.pi
            if not animate(rollingGear, 1.5, {
                Position = UDim2.new(1, 80, 0.5, 0), Rotation = rotation,
            }, Enum.EasingStyle.Linear) then return end
            rollingGear:Destroy()
            rollingGear = nil
        end
        logo.ImageTransparency = 0
        if not animate(reveal, 0.7, {Size = UDim2.fromOffset(520, 350)}) then return end
        task.wait(0.45)
        if not animate(intro, 0.25, {GroupTransparency = 1, Position = UDim2.new(0.5, 0, 0.5, -18)}) then return end
    end)
    if intro then intro:Destroy() end
    if rollingGear then rollingGear:Destroy() end
    if not ok then warn("[HalloweenHatDelivery] Intro skipped: " .. tostring(err)) end
    if alive then
        panel.Visible = true
        panelScale.Scale = 0.68
        animate(panelScale, 0.35, {Scale = 0.8}, Enum.EasingStyle.Back)
    end
end)
for _, surface in ipairs({credit, speedLabel, status}) do table.insert(dragSurfaces, surface) end
for _, surface in ipairs(dragSurfaces) do
    surface.Active = true
    connect(surface.InputBegan, function(input)
        if not sliding and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            dragging, dragStart, panelStart, dragInput = true, input.Position, panel.Position, input
        end
    end)
end
connect(UIS.InputChanged, function(input)
    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        if sliding and (input.UserInputType == Enum.UserInputType.MouseMovement or input == sliderTouch) then slide(input.Position.X) end
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input == dragInput) then
            local delta = input.Position - dragStart
            panel.Position = UDim2.new(panelStart.X.Scale, panelStart.X.Offset + delta.X, panelStart.Y.Scale, panelStart.Y.Offset + delta.Y)
        end
    end
end)
connect(UIS.InputEnded, function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input == sliderTouch then sliding, sliderTouch = false, nil end
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input == dragInput then dragging, dragInput = false, nil end
    end
end)

local function root()
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local part = character and character:FindFirstChild("HumanoidRootPart")
    if humanoid and humanoid.Health > 0 then return part end
end
local function promptPosition(prompt)
    local parent = prompt.Parent
    if parent and parent:IsA("Attachment") then return parent.WorldPosition end
    if parent and parent:IsA("BasePart") then return parent.Position end
    if parent and parent:IsA("Model") then return parent:GetPivot().Position end
end
local function findPrompt()
    local best, distance = nil, math.huge
    for _, object in ipairs(workspace:GetDescendants()) do
        if object:IsA("ProximityPrompt") and object.Enabled then
            local position = promptPosition(object)
            local text = string.lower(object.ActionText .. " " .. object.ObjectText .. " " .. object.Name)
            if position then
                local d = (position - PICKUP.Position).Magnitude
                if d < 25 and d < distance and (string.find(text, "hat", 1, true) or object.KeyboardKeyCode == Enum.KeyCode.E) then
                    best, distance = object, d
                end
            end
        end
    end
    return best
end
local function deliveryParts()
    local halloween = workspace:FindFirstChild("Halloween")
    local folder = halloween and halloween:FindFirstChild("DeliveryPoints")
    local parts = {}
    for i = 1, 4 do
        local point = folder and folder:FindFirstChild(tostring(i))
        local touch = point and point:FindFirstChild("Touch", true)
        if not touch or not touch:IsA("BasePart") then return nil end
        parts[i] = touch
    end
    return parts
end
local function markedDelivery(parts)
    local selected
    for i, part in ipairs(parts) do
        if part.Parent:FindFirstChild("HatNavEnd", true) then
            -- Wait until exactly one destination is marked.
            if selected then return nil end
            selected = i
        end
    end
    return selected
end
local function active(token, characterRoot)
    return alive and enabled and generation == token and root() == characterRoot
end
local function pause(seconds, token, characterRoot)
    local deadline = os.clock() + seconds
    repeat
        if not active(token, characterRoot) then return false end
        task.wait(math.min(0.02, math.max(0, deadline - os.clock())))
    until os.clock() >= deadline
    return active(token, characterRoot)
end
local heldPrompt
local function stopWalking()
    local characterRoot = root()
    local humanoid = characterRoot and characterRoot.Parent:FindFirstChildOfClass("Humanoid")
    if humanoid then humanoid:MoveTo(characterRoot.Position) end
end
local function pickupInRange(characterRoot)
    local prompt = findPrompt()
    local position = prompt and promptPosition(prompt)
    return position ~= nil and (characterRoot.Position - position).Magnitude <= math.max(0, prompt.MaxActivationDistance - 0.5)
end
local function walkTo(destination, token, characterRoot, keepGoing, arrivalCheck)
    local humanoid = characterRoot.Parent:FindFirstChildOfClass("Humanoid")
    local function needed()
        return active(token, characterRoot) and (not keepGoing or keepGoing())
    end
    local function near(position, radius)
        local delta = characterRoot.Position - position
        return Vector2.new(delta.X, delta.Z).Magnitude <= radius and math.abs(delta.Y) <= 7
    end
    while needed() do
        if arrivalCheck and arrivalCheck() then stopWalking(); return true end
        if near(destination, 2.5) then stopWalking(); return true end
        local path = PathfindingService:CreatePath({AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 5})
        local ok = pcall(function() path:ComputeAsync(characterRoot.Position, destination) end)
        if not needed() then return false end
        if arrivalCheck and arrivalCheck() then stopWalking(); return true end
        if ok and path.Status == Enum.PathStatus.Success then
            local waypoints = path:GetWaypoints()
            for index = 2, #waypoints do
                if not needed() then stopWalking(); return false end
                if arrivalCheck and arrivalCheck() then stopWalking(); return true end
                local waypoint = waypoints[index]
                local segmentStart = characterRoot.Position
                local segment = Vector3.new(waypoint.Position.X - segmentStart.X, 0, waypoint.Position.Z - segmentStart.Z)
                local function reachedWaypoint()
                    if near(waypoint.Position, 2) then return true end
                    if index == #waypoints or segment.Magnitude < 0.01 then return false end
                    local offset = characterRoot.Position - waypoint.Position
                    local horizontal = Vector3.new(offset.X, 0, offset.Z)
                    local direction = segment.Unit
                    -- Advance when crossing the waypoint plane, even between frames.
                    local passed = horizontal:Dot(direction)
                    local sideways = (horizontal - direction * passed).Magnitude
                    return passed >= 0 and sideways <= 4 and math.abs(offset.Y) <= 7
                end
                if waypoint.Action == Enum.PathWaypointAction.Jump then humanoid.Jump = true end
                humanoid:MoveTo(waypoint.Position)
                local lastPosition, progressAt, refreshedAt = characterRoot.Position, os.clock(), os.clock()
                local waypointDeadline = os.clock() + math.max(3, segment.Magnitude / math.max(1, speed) * 3)
                local stuck = false
                while needed() and not reachedWaypoint() do
                    if not pause(0.02, token, characterRoot) then return false end
                    if arrivalCheck and arrivalCheck() then stopWalking(); return true end
                    if (characterRoot.Position - lastPosition).Magnitude >= 1 then
                        lastPosition, progressAt = characterRoot.Position, os.clock()
                    end
                    if os.clock() - progressAt > 0.8 or os.clock() > waypointDeadline then stuck = true; break end
                    if os.clock() - refreshedAt > 0.3 then
                        humanoid:MoveTo(waypoint.Position)
                        refreshedAt = os.clock()
                    end
                end
                if stuck then break end -- Recompute a route if blocked.
            end
        else
            status.Text = "No walking route; retrying..."
        end
        if not pause(0.2, token, characterRoot) then return false end
    end
    stopWalking()
    return false
end
local function deliver(parts, selected, token, characterRoot)
    local part = parts[selected]
    if not active(token, characterRoot) or not part:IsDescendantOf(workspace) then return false end
    status.Text = "Walking to delivery point " .. selected
    local function markerPresent()
        return part:IsDescendantOf(workspace) and part.Parent:FindFirstChild("HatNavEnd", true) ~= nil
    end
    local arrived = walkTo(DELIVERY_POSITIONS[selected].Position, token, characterRoot, markerPresent)
    if not active(token, characterRoot) then return false end
    if not arrived and markerPresent() then return false end
    while part:IsDescendantOf(workspace) and part.Parent:FindFirstChild("HatNavEnd", true) do
        status.Text = "Waiting for HatNavEnd to disappear: " .. selected
        if not pause(0.1, token, characterRoot) then return false end
    end
    return active(token, characterRoot) and part:IsDescendantOf(workspace)
end
local function cycle(token, characterRoot)
    local parts = deliveryParts()
    if not parts then status.Text = "Waiting for delivery points 1–4 to load"; pause(1, token, characterRoot); return end
    -- An existing endpoint means a hat delivery is already in progress.
    -- Complete it before looking for the pickup prompt, which may be hidden.
    local existing = markedDelivery(parts)
    if existing and not deliver(parts, existing, token, characterRoot) then return end
    if not active(token, characterRoot) then return end
    status.Text = "Walking back to hat..."
    if not walkTo(PICKUP.Position, token, characterRoot, nil, function() return pickupInRange(characterRoot) end) then return end
    if not pause(0.35, token, characterRoot) then return end
    parts = deliveryParts()
    if not parts then status.Text = "Waiting for delivery points 1–4 to load"; pause(1, token, characterRoot); return end
    local prompt = findPrompt()
    if not prompt then status.Text = "Waiting for the hat's E prompt"; pause(1, token, characterRoot); return end
    status.Text = "Taking the hat..."
    -- Activate the E proximity interaction, respecting its configured hold time.
    heldPrompt = prompt
    prompt:InputHoldBegin()
    local completed = pause(prompt.HoldDuration + 0.15, token, characterRoot)
    prompt:InputHoldEnd()
    heldPrompt = nil
    if not completed or not pause(0.2, token, characterRoot) then return end
    -- Wait for the destination, then stay there until its marker disappears.
    local selected
    local pickupDeadline = os.clock() + 3
    repeat
        status.Text = "Waiting for HatNavEnd..."
        if not pause(0.1, token, characterRoot) then return end
        parts = deliveryParts()
        selected = parts and markedDelivery(parts)
        if not selected and os.clock() >= pickupDeadline then
            status.Text = "Pickup not confirmed; retrying E..."
            return
        end
    until selected
    deliver(parts, selected, token, characterRoot)
end
connect(toggle.Activated, function()
    enabled = not enabled
    generation = generation + 1
    if heldPrompt then pcall(function() heldPrompt:InputHoldEnd() end); heldPrompt = nil end
    toggle.Text = "Hat Delivery: " .. (enabled and "ON" or "OFF")
    toggle.BackgroundColor3 = enabled and Color3.fromRGB(105, 48, 137) or Color3.fromRGB(65, 32, 73)
    if not enabled then stopWalking(); status.Text = "Stopped" end
end)
connect(gui.Destroying, function()
    alive, enabled = false, false
    generation = generation + 1
    stopWalking()
    if heldPrompt then pcall(function() heldPrompt:InputHoldEnd() end) end
    for _, c in ipairs(connections) do c:Disconnect() end
end)
connect(close.Activated, function() gui:Destroy() end)
task.spawn(function()
    while alive do
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            humanoid.WalkSpeed = speed
        end
        task.wait(0.03)
    end
end)
task.spawn(function()
    while alive do
        if enabled then
            local characterRoot, token = root(), generation
            if characterRoot then
                local ok = pcall(cycle, token, characterRoot)
                if not ok and active(token, characterRoot) then
                    stopWalking()
                    status.Text = "Interaction unavailable; retrying..."
                    pause(1, token, characterRoot)
                end
            else status.Text = "Waiting for character..." end
        end
        task.wait(0.1)
    end
end)
